import (
	"fmt"
	"sync"
)

// sprintfBinding implements String by formatting values from other bindings using fmt.Sprintf
type sprintfBinding struct {
	base
	format string
	sources []DataItem
	cache   string
	mu      sync.RWMutex
}

// NewSprintf returns a String binding that formats its value using fmt.Sprintf.
// The format string is applied to the values from the source bindings.
// The returned binding updates automatically when any source changes.
func NewSprintf(format string, sources ...DataItem) String {
	if len(sources) == 0 {
		// Return a static string if no sources
		ret := &sprintfBinding{format: format, sources: nil}
		ret.cache = format
		return ret
	}

	ret := &sprintfBinding{format: format, sources: sources}
	ret.update()

	// Listen to all source bindings
	for _, source := range sources {
		source.AddListener(ret)
	}

	return ret
}

func (s *sprintfBinding) Get() (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.cache, nil
}

func (s *sprintfBinding) Set(string) error {
	return fmt.Errorf("sprintf binding is read-only")
}

func (s *sprintfBinding) DataChanged() {
	s.update()
	s.trigger()
}

func (s *sprintfBinding) update() {
	if len(s.sources) == 0 {
		return
	}

	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := source.(DataItem).Get()
		if err != nil {
			values[i] = "<error>"
			continue
		}
		values[i] = val
	}

	s.mu.Lock()
	s.cache = fmt.Sprintf(s.format, values...)
	s.mu.Unlock()
}

// StringToStringWithFormat creates a String binding that formats another String binding
func StringToStringWithFormat(source String, format string) String {
	if source == nil {
		return NewString()
	}
	return NewSprintf(format, source)
}
