// parseHexColor parses a hex color string supporting 3, 4, 6, or 8 digit formats
// with or without the '#' prefix.
func parseHexColor(hex string) (color.Color, error) {
	// Remove '#' prefix if present
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3:
		// RGB format: expand each digit (e.g., "abc" -> "aabbcc")
		vals := make([]uint8, 3)
		for i := 0; i < 3; i++ {
			v, err := strconv.ParseUint(string(hex[i]), 16, 8)
			if err != nil {
				return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
			}
			vals[i] = uint8(v)
			vals[i] = vals[i]<<4 | vals[i]
		}
		r, g, b = vals[0], vals[1], vals[2]

	case 4:
		// RGBA format: expand each digit (e.g., "abcd" -> "aabbccdd")
		vals := make([]uint8, 4)
		for i := 0; i < 4; i++ {
			v, err := strconv.ParseUint(string(hex[i]), 16, 8)
			if err != nil {
				return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
			}
			vals[i] = uint8(v)
			vals[i] = vals[i]<<4 | vals[i]
		}
		r, g, b, a = vals[0], vals[1], vals[2], vals[3]

	case 6:
		// RRGGBB format
		v, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8(v >> 16)
		g = uint8(v >> 8)
		b = uint8(v)

	case 8:
		// RRGGBBAA format
		v, err := strconv.ParseUint(hex, 16, 64)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8(v >> 24)
		g = uint8(v >> 16)
		b = uint8(v >> 8)
