import (
	"fmt"
	"sync"

	"fyne.io/fyne/v2/storage"
)

// sprintfBinding implements String by formatting values from other bindings using fmt.Sprintf
type sprintfBinding struct {
	base
	format   string
	sources  []DataItem
	cache    string
	lastErr  error
	mu       sync.RWMutex
}

// NewSprintf returns a String binding that formats its value using fmt.Sprintf.
// The format string is applied to the values from the source bindings.
// The returned binding updates automatically when any source changes.
func NewSprintf(format string, sources ...DataItem) String {
	if len(sources) == 0 {
		// Return a static string if no sources
		ret := &sprintfBinding{format: format, sources: nil}
		ret.cache = format
		return ret
	}

	ret := &sprintfBinding{format: format, sources: sources}
	ret.update()

	// Listen to all source bindings
	for _, source := range sources {
		source.AddListener(ret)
	}

	return ret
}

func (s *sprintfBinding) Get() (string, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	return s.cache, s.lastErr
}

func (s *sprintfBinding) Set(str string) error {
	if len(s.sources) == 0 {
		return fmt.Errorf("sprintf binding with no sources is read-only")
	}

	// Prepare pointers for Sscanf to write into
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		switch source.(type) {
		case String:
			var v string
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Float:
			var v float64
			values[i] = &v
		case Bool:
			var v bool
			values[i] = &v
		case Bytes:
			// Bytes cannot round-trip through string formatting
			return fmt.Errorf("cannot set Bytes binding through sprintf")
		case URI:
			var v string
			values[i] = &v
		default:
			return fmt.Errorf("unsupported binding type for sprintf Set")
		}
	}

	// Parse the string using Sscanf
	_, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return err
	}

	// Set each source binding with the parsed value
	for i, source := range s.sources {
		switch src := source.(type) {
		case String:
			if err := src.Set(*values[i].(*string)); err != nil {
				return err
			}
		case Int:
			if err := src.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Float:
			if err := src.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Bool:
			if err := src.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case URI:
			uriStr := *values[i].(*string)
			uri, err := storage.ParseURI(uriStr)
			if err != nil {
				return err
			}
			if err := src.Set(uri); err != nil {
				return err
			}
		}
	}

	return nil
}

func (s *sprintfBinding) DataChanged() {
	s.update()
	s.trigger()
}

func (s *sprintfBinding) update() {
	if len(s.sources) == 0 {
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	s.lastErr = nil
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := source.(DataItem).Get()
		if err != nil {
			// Track the error and use placeholder
			if s.lastErr == nil {
				s.lastErr = err
			}
			values[i] = "<error>"
			continue
		}
		values[i] = val
	}

	s.cache = fmt.Sprintf(s.format, values...)
}

// StringToStringWithFormat creates a String binding that formats another String binding.
// If the format is "%s" (identity), returns the original binding directly (no wrapping).
func StringToStringWithFormat(source String, format string) String {
	if source == nil {
		return NewString()
	}
	// Optimization: if format is identity, return source directly
	if format == "%s" {
		return source
	}
	return NewSprintf(format, source)
}
