import "fyne.io/fyne/v2"

// NewAllStrings creates a validator combinator that runs all provided validators in sequence.
// It returns a StringValidator that executes each validator in order and returns the first
// error encountered. If all validators pass, it returns nil.
//
// This enables chaining multiple validators together, such as combining time format validation
// with regexp validation, or multiple regexp patterns that all must pass.
//
// Example:
//   validator := validation.NewAllStrings(
//       validation.NewRegexp(`^\d{4}$`, "must be 4 digits"),
//       validation.NewTime("2006"),
//   )
//
// Since: 2.1
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}
